 shell/autotests/CMakeLists.txt          |   1 +
 shell/shellcorona.cpp                   |   3 +
 shell/shellcorona.h                     |   6 ++
 7 files changed, 190 insertions(+)
 create mode 100644 libtaskmanager/unitylauncherentries.cpp
 create mode 100644 libtaskmanager/unitylauncherentries.h

