new file mode 100644
index 0000000000..c8f5176ea1
--- /dev/null
+++ b/libtaskmanager/unitylauncherentries.cpp
@@ -0,0 +1,103 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include "unitylauncherentries.h"
+
+#include <QDBusConnection>
+#include <QDBusMessage>
+#include <QDBusServiceWatcher>
+
+#include "libtaskmanager_debug.h"
+
+namespace TaskManager
+{
+UnityLauncherEntries::UnityLauncherEntries()
+    : m_watcher(new QDBusServiceWatcher(this))
+{
+    auto sessionBus = QDBusConnection::sessionBus();
+
+    m_watcher->setConnection(sessionBus);
+    m_watcher->setWatchMode(QDBusServiceWatcher::WatchForUnregistration);
+    connect(m_watcher, &QDBusServiceWatcher::serviceUnregistered, this, &UnityLauncherEntries::onServiceUnregistered);
+
+    if (!sessionBus.connect({},
+                            {},
+                            QStringLiteral("com.canonical.Unity.LauncherEntry"),
+                            QStringLiteral("Update"),
+                            this,
+                            SLOT(update(QString, QVariantMap, QDBusMessage)))) {
+        qCWarning(TASKMANAGER_DEBUG) << "Failed to connect to the Unity LauncherEntry Update signal";
+        return;
+    }
+
+    if (!sessionBus.registerObject(QStringLiteral("/Unity"), this)) {
+        qCWarning(TASKMANAGER_DEBUG) << "Failed to register the Unity object";
+        return;
+    }
+
+    if (!sessionBus.registerService(QStringLiteral("com.canonical.Unity"))) {
+        // In case an external process uses this (e.g. Latte Dock), let it just listen.
+        qCWarning(TASKMANAGER_DEBUG) << "Failed to register the Unity service";
+    }
+}
+
+UnityLauncherEntries::~UnityLauncherEntries() = default;
+
+std::shared_ptr<UnityLauncherEntries> UnityLauncherEntries::instance()
+{
+    static std::weak_ptr<UnityLauncherEntries> s_instance;
+    if (auto ptr = s_instance.lock()) {
+        return ptr;
+    }
+    std::shared_ptr<UnityLauncherEntries> ptr(new UnityLauncherEntries);
+    s_instance = ptr;
+    return ptr;
+}
+
+QHash<QString, QVariantMap> UnityLauncherEntries::entries() const
+{
+    QHash<QString, QVariantMap> entries;
+    entries.reserve(m_entries.size());
+    for (auto it = m_entries.constBegin(); it != m_entries.constEnd(); ++it) {
+        entries.insert(it.key(), it->properties);
+    }
+    return entries;
+}
+
+void UnityLauncherEntries::update(const QString &uri, const QVariantMap &properties, const QDBusMessage &message)
+{
+    Entry &entry = m_entries[uri];
+
+    if (entry.service != message.service()) {
+        entry.service = message.service();
+        m_watcher->addWatchedService(entry.service);
+    }
+
+    for (auto it = properties.constBegin(); it != properties.constEnd(); ++it) {
+        entry.properties.insert(it.key(), it.value());
+    }
+
+    Q_EMIT updated(uri, properties);
+}
+
+void UnityLauncherEntries::onServiceUnregistered(const QString &service)
+{
+    m_watcher->removeWatchedService(service);
+
+    for (auto it = m_entries.begin(); it != m_entries.end();) {
+        if (it->service == service) {
+            const QString uri = it.key();
+            it = m_entries.erase(it);
+            Q_EMIT removed(uri);
+        } else {
+            ++it;
+        }
+    }
+}
+
+}
+
+#include "moc_unitylauncherentries.cpp"
diff --git a/libtaskmanager/unitylauncherentries.h b/libtaskmanager/unitylauncherentries.h
new file mode 100644
index 0000000000..b2016a126c
--- /dev/null
+++ b/libtaskmanager/unitylauncherentries.h
@@ -0,0 +1,74 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#pragma once
+
+#include <QHash>
+#include <QObject>
+#include <QVariantMap>
+
+#include <memory>
+
+#include "taskmanager_export.h"
+
+class QDBusMessage;
+class QDBusServiceWatcher;
+
+namespace TaskManager
+{
+/**
+ * @short Keeps the Unity Launcher API entries sent by applications.
+ *
+ * This class owns the com.canonical.Unity service and records the latest
+ * com.canonical.Unity.LauncherEntry properties (count, progress, urgent…)
+ * each application sent, until the application leaves the session bus.
+ *
+ * The shell creates it early on, so that entries sent by applications
+ * started before a task manager is loaded are not lost.
+ **/
+class TASKMANAGER_EXPORT UnityLauncherEntries : public QObject
+{
+    Q_OBJECT
+
+public:
+    ~UnityLauncherEntries() override;
+
+    static std::shared_ptr<UnityLauncherEntries> instance();
+
+    /**
+     * The launcher URIs, as sent by the applications (e.g. "application://foo.desktop"),
+     * mapped to all the properties last sent for them.
+     */
+    QHash<QString, QVariantMap> entries() const;
+
+Q_SIGNALS:
+    /**
+     * An application sent an update for @p uri with the given @p properties.
+     */
+    void updated(const QString &uri, const QVariantMap &properties);
+    /**
+     * The application that sent @p uri left the session bus.
+     */
+    void removed(const QString &uri);
+
+private Q_SLOTS:
+    void update(const QString &uri, const QVariantMap &properties, const QDBusMessage &message);
+
+private:
+    UnityLauncherEntries();
+
+    void onServiceUnregistered(const QString &service);
+
+    struct Entry {
+        QString service;
+        QVariantMap properties;
+    };
+
+    QDBusServiceWatcher *const m_watcher;
+    QHash<QString, Entry> m_entries;
+};
+
+}
